contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount, uint depositAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(amount > 0);
        require(depositAmt >= amount);
        require(address(this).balance >= depositAmt);
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cbalBefore = address(c).balance;
        uint selfBefore = address(this).balance;
        c.Collect(amount); if (__ESBMC_reverted()) return;
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cbalAfter = address(c).balance;
        assert(balBefore - balAfter == amount && cbalBefore - cbalAfter == amount && address(this).balance - selfBefore == amount && balAfter == depositAmt - amount);
    }
    receive() external payable {}
    fallback() external payable {}
}

