pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 amount, uint256 depositAmt) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(depositAmt >= amount);
        vm.assume(address(this).balance >= depositAmt);
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.SetMinSum(0) {} catch { return; }
        try c.Deposit{value: depositAmt}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint cbalBefore = address(c).balance;
        uint selfBefore = address(this).balance;
        try c.Collect(amount) {} catch { return; }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint cbalAfter = address(c).balance;
        assertTrue(balBefore - balAfter == amount && cbalBefore - cbalAfter == amount && address(this).balance - selfBefore == amount && balAfter == depositAmt - amount);
    }

    function testFuzz_run(uint256 amount, uint256 depositAmt) public {
        _run(amount, depositAmt);
    }

    receive() external payable {}

    fallback() external payable {}
}
